SELECT CASE WHEN duration_sec >= 476 THEN 'high' WHEN duration_sec >= 187 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, MONTH(event_time) AS event_month, COUNT(*) AS num_web_events, SUM(CASE WHEN event_type = 'click' THEN duration_sec ELSE 0 END) AS click_duration_sec, ROUND((100 * SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout FROM web_events GROUP BY CASE WHEN duration_sec >= 476 THEN 'high' WHEN duration_sec >= 187 THEN 'mid' ELSE 'low' END, MONTH(event_time) HAVING num_web_events >= 2 ORDER BY pct_checkout
